sp_widget.client_script:
api.controller = function($scope, $window) {

    var c = this;

    c.loading = true;
    c.error = "";
    c.interview = null;
    c.result = "";
    c.feedback = "";
    c.saving = false;


    /*
     * BACK TO INTERVIEW MANAGEMENT
     */

    c.backToInterviews = function() {

        $window.location.href =
            "?id=campus360_recruiter_interviews";

    };


    /*
     * GET INTERVIEW
     */

    if (c.data && c.data.interview) {

        c.interview = c.data.interview;

        c.result = c.interview.result || "";
        c.feedback = c.interview.feedback || "";

        c.loading = false;

    } else {

        c.loading = false;
        c.error = "Interview record could not be found.";

    }


    /*
     * UPDATE RESULT
     */

    c.updateResult = function() {

        if (!c.result) {
            alert("Please select an interview result.");
            return;
        }

        c.saving = true;

        c.server.get({
            action: "update_result",
            sys_id: c.interview.sys_id,
            result: c.result,
            feedback: c.feedback
        }).then(function(response) {

            c.saving = false;

            if (response.data.success) {

                alert("Interview result updated successfully.");

                c.interview.result =
                    response.data.result;

                c.interview.feedback =
                    response.data.feedback;

            } else {

                alert(
                    response.data.error ||
                    "Unable to update interview."
                );

            }

        });

    };

};

sp_widget.css:
.interview-details-page {
    max-width: 1100px;
    margin: 0 auto;
    padding: 30px;
    background: #f5f7fb;
    min-height: 100vh;
    font-family: Arial, sans-serif;
}


/* HEADER */

.details-header {
    background: #ffffff;
    border: 1px solid #dce3f0;
    border-radius: 16px;
    padding: 28px 32px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 22px;
}

.eyebrow {
    color: #4d63e8;
    font-size: 12px;
    font-weight: 700;
    letter-spacing: 2px;
    margin-bottom: 8px;
}

.details-header h1 {
    margin: 0;
    color: #082b5c;
    font-size: 30px;
}

.details-header p {
    margin: 8px 0 0;
    color: #718096;
}


/* BUTTONS */

.btn-back,
.btn-secondary {
    background: #ffffff;
    border: 1px solid #cbd5e1;
    color: #173f78;
    padding: 11px 18px;
    border-radius: 8px;
    cursor: pointer;
}

.btn-primary {
    background: #5367e8;
    border: none;
    color: #ffffff;
    padding: 11px 20px;
    border-radius: 8px;
    cursor: pointer;
    font-weight: 600;
}

.btn-primary:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}


/* CARDS */

.section-card {
    background: #ffffff;
    border: 1px solid #dce3f0;
    border-radius: 14px;
    padding: 25px;
    margin-bottom: 20px;
    box-shadow: 0 3px 12px rgba(20, 50, 100, 0.04);
}

.section-title {
    font-size: 18px;
    font-weight: 600;
    color: #123b70;
    padding-bottom: 15px;
    border-bottom: 1px solid #e5eaf2;
    margin-bottom: 20px;
}

.section-description {
    color: #718096;
    font-size: 14px;
}


/* INFORMATION GRID */

.info-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 22px 40px;
}

.info-item {
    display: flex;
    flex-direction: column;
    gap: 6px;
}

.info-item span {
    color: #718096;
    font-size: 12px;
}

.info-item strong {
    color: #173f78;
    font-size: 15px;
}

.full-width {
    grid-column: 1 / -1;
}


/* MEETING */

.meeting-link {
    color: #4d63e8;
    font-weight: 600;
    text-decoration: none;
}

.meeting-link:hover {
    text-decoration: underline;
}


/* STATUS */

.status-row {
    display: flex;
    gap: 100px;
}

.status-row > div {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.status-row span {
    color: #718096;
    font-size: 12px;
}

.status-row strong {
    color: #173f78;
}

.status-badge {
    display: inline-block;
    background: #eef1ff;
    color: #4d63e8;
    padding: 6px 12px;
    border-radius: 7px;
    font-size: 12px;
    font-weight: 600;
}


/* FORM */

.result-form {
    display: flex;
    flex-direction: column;
    gap: 18px;
}

.form-group {
    display: flex;
    flex-direction: column;
    gap: 7px;
}

.form-group label {
    color: #173f78;
    font-size: 13px;
    font-weight: 600;
}

.form-group select,
.form-group textarea {
    width: 100%;
    border: 1px solid #ccd6e5;
    border-radius: 8px;
    padding: 11px 12px;
    font-size: 14px;
    box-sizing: border-box;
}

.form-group textarea {
    min-height: 110px;
    resize: vertical;
}

.form-group select:focus,
.form-group textarea:focus {
    outline: none;
    border-color: #5367e8;
}


/* ACTIONS */

.action-row {
    display: flex;
    justify-content: flex-end;
    gap: 12px;
    margin-top: 22px;
}


/* LOADING / ERROR */

.loading-card,
.error-card {
    background: #ffffff;
    border: 1px solid #dce3f0;
    border-radius: 14px;
    padding: 40px;
    text-align: center;
}

.error-card {
    color: #b42318;
}


/* MOBILE */

@media (max-width: 700px) {

    .interview-details-page {
        padding: 15px;
    }

    .details-header {
        flex-direction: column;
        align-items: flex-start;
        gap: 20px;
    }

    .info-grid {
        grid-template-columns: 1fr;
    }

    .full-width {
        grid-column: auto;
    }

    .status-row {
        flex-direction: column;
        gap: 20px;
    }
}

sp_widget.script:
(function() {

    data.interview = null;
    data.success = false;
    data.error = "";


    /*
     * GET SYS_ID FROM URL
     */

    var sysId = $sp.getParameter("sys_id");


    if (!sysId) {

        data.error = "No interview was selected.";
        return;

    }


    /*
     * UPDATE RESULT
     */

    if (input && input.action == "update_result") {

        var updateGR = new GlideRecord(
            "x_snc_campus360_recruiter_interview"
        );

        if (!updateGR.get(input.sys_id)) {

            data.error = "Interview record not found.";
            return;

        }


        updateGR.setValue(
            "result",
            input.result
        );

        updateGR.setValue(
            "feedback",
            input.feedback || ""
        );


        /*
         * Mark interview completed
         */

        updateGR.setValue(
            "status",
            "Completed"
        );


        updateGR.update();


        data.success = true;
        data.result =
            updateGR.getDisplayValue("result");

        data.feedback =
            updateGR.getValue("feedback");

        return;

    }


    /*
     * GET INTERVIEW RECORD
     */

    var gr = new GlideRecord(
        "x_snc_campus360_recruiter_interview"
    );


    if (!gr.get(sysId)) {

        data.error = "Interview record not found.";
        return;

    }


    var interview = {};

    interview.sys_id =
        gr.getUniqueValue();

    interview.interview_id =
        gr.getValue("interview_id");

    interview.student =
        gr.getDisplayValue("student");

    interview.application =
        gr.getDisplayValue("application");

    interview.opportunity =
        gr.getDisplayValue("opportunity");

    interview.round =
        gr.getDisplayValue("interview_round");

    interview.mode =
        gr.getDisplayValue("interview_mode");

    interview.interviewer =
        gr.getValue("interviewer");

    interview.interview_date =
        gr.getDisplayValue("interview_date");

    interview.meeting_link =
        gr.getValue("meeting_link");

    interview.status =
        gr.getDisplayValue("status");

    interview.result =
        gr.getDisplayValue("result");

    interview.feedback =
        gr.getValue("feedback");


    data.interview = interview;

})();
